#include <stdio.h>
struct Record {int id; int score;};
int set_score(struct Record *record,int value) {record->score=value; if(value<0 || value>100) return 0; return 1;}
int main(void) {struct Record record={7,80};
int accepted=set_score(&record,101);
printf("accepted=%d id=%d score=%d\n",accepted,record.id,record.score);return 0;}

